#pragma once
#include "kstationStartupServicesTask.h"
#include "kstationNativeForeground.h"
#include "kstationNativeDspTransfer.h"
#include <variant>
namespace kstation {
class NativeStartupServices final {
 using S=StartupSchedulerTask;using C=StartupClockTask;using A=StartupAdcReadTask;using V=StartupVolumeTask;using R=StartupArpStateTask;
 struct Job{std::variant<S,C,A,V,R>task;};
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,9>CodeRanges{{{0x5cc,0x5ee},{0x3402,0x342a},{0x388c,0x38b0},{0x38e8,0x390c},{0x3944,0x3968},{0x39a0,0x39c4},{0x39fc,0x3a20},{0x403c,0x4054},{0x4444,0x4454}}};
 bool active()const{return depth_||foreground_.active()||dsp_.active();}void reset(){depth_=0;foreground_.reset();dsp_.reset();steps_=0;}uint64_t steps()const{return steps_;}
 static bool candidate(uint32_t at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(at>=0x9aa&&at<0x9b6){if(!foreground_.step(c).stepped)return false;++steps_;return true;}if(NativeDspTransfer::candidate(at)){if(!dsp_.step(c))return false;++steps_;return true;}
  if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;bool admitted=false;for(unsigned slot=0;slot<5;++slot){if(at==0x388c+0x5c*slot||at==0x3896+0x5c*slot){j.task.emplace<S>(slot,at==0x3896+0x5c*slot,uint32_t(c.reg32(5)),uint16_t(c.reg16(6)));admitted=true;break;}}if(!admitted){if(at==0x5cc)j.task.emplace<A>(uint8_t(c.reg8(14)));else if(at==0x403c)j.task.emplace<V>(uint8_t(c.reg8(6)));else if(at==0x3402)j.task.emplace<R>();else if(at==0x4444)j.task.emplace<C>();else return false;}if(depth_==jobs_.size())throw std::logic_error("Native K startup service capacity");jobs_[depth_++]=j;}
  auto&j=jobs_[depth_-1];resume(j,c);if(at!=boundary(j))throw std::logic_error("Native K startup service boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
  std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,S>)t.advanceBefore(cost,cr,[&](S::Write field,unsigned value){auto delay=0xcd44+8*t.slot();if(field==S::Write::Callback){c.write32(int32_t(value),delay+2);val(c,c.reg32(5));}else{unsigned address=field==S::Write::Tick?delay-2:delay;c.write16(int16_t(value),address);val(c,c.reg16(field==S::Write::Clear?0:6));}});else if constexpr(std::is_same_v<T,A>)t.advanceBefore(cost,cr,[&]{c.reg16(0)=int16_t(c.read16(0xc3d0+t.offset()));val(c,c.reg16(0));return uint16_t(c.reg16(0));});else if constexpr(std::is_same_v<T,R>)t.advanceBefore(cost,cr,[&]{c.reg32(0)=int32_t(c.read32(0xfffe50));val(c,c.reg32(0));return uint32_t(c.reg32(0));},[&](R::Write field,unsigned value){unsigned address=field==R::Write::Flags?0xcd3d:field==R::Write::Note?0xcd34:field==R::Write::Phase?0xcd2c:0xcd28;if(field==R::Write::Flags)c.write8(int8_t(value),address);else if(field==R::Write::Note)c.write16(int16_t(value),address);else c.write32(int32_t(value),address);val(c,field==R::Write::Flags?c.reg8(8):field==R::Write::Note?c.reg16(0):c.reg32(0));});else t.advanceBefore(cost,cr);},j.task);
  if(c.cycles-begin!=cost)throw std::logic_error("Native K startup service clocks differ");auto done=std::visit([](const auto&t){return t.complete();},j.task);if(done)--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;
 }
private:
 static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static bool waiting(const Job&j){return std::visit([](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,S>||std::is_same_v<T,C>||std::is_same_v<T,V>)return t.awaiting();else return false;},j.task);}
 static void resume(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<S>(&j.task)){if(t->awaiting())t->resume(uint16_t(c.reg16(6)));}else if(auto*t=std::get_if<C>(&j.task)){if(t->awaiting())t->resume();}else if(auto*t=std::get_if<V>(&j.task)){if(t->awaiting())t->resume();}}
 static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,S>){using Q=S::Stage;unsigned base=0x388c+0x5c*t.slot();switch(t.stage()){case Q::Clear:return base;case Q::PublishClear:return base+2;case Q::PublishCallback:return base+10;case Q::PublishDelay:return base+18;case Q::ReadTick:return base+24;case Q::PublishTick:return base+28;case Q::Return:return base+(t.armed()?34:8);default:return 0;}}else if constexpr(std::is_same_v<T,C>){static constexpr unsigned a[]={0x4444,0x4448,0x444e,0x4452,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,A>){static constexpr unsigned a[]={0x5cc,0x5d0,0x5d2,0x5d4,0x5d6,0x5dc,0x5de,0x5e2,0x5e4,0x5e6,0x5e8,0x5ec,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<T,V>){static constexpr unsigned a[]={0x403c,0x403e,0x4040,0x4042,0x4044,0x4046,0x4048,0x404c,0x4050,0x4052,0};return a[unsigned(t.stage())];}else{static constexpr unsigned a[]={0x3402,0x3404,0x340a,0x3410,0x3418,0x3420,0x3428,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){if(auto*t=std::get_if<S>(&j.task)){using Q=S::Stage;switch(t->stage()){case Q::PublishCallback:return 8;case Q::PublishClear:case Q::PublishDelay:case Q::PublishTick:return 6;case Q::ReadTick:return 4;default:return 2;}}switch(boundary(j)){case 0x5cc:case 0x5de:case 0x5e8:case 0x4048:case 0x404c:case 0x4444:case 0x444e:return 4;case 0x5d6:case 0x3404:case 0x340a:case 0x4448:return 6;case 0x3410:case 0x3418:case 0x3420:return 8;default:return 2;}}
 static unsigned bus(uint32_t at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=uint32_t(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,last);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);if(auto*t=std::get_if<S>(&j.task)){using Q=S::Stage;auto delay=0xcd44+8*t->slot();switch(t->stage()){case Q::PublishClear:case Q::PublishDelay:cr.write=bus(delay,2,c.writeHistory());break;case Q::PublishCallback:cr.write=bus(delay+2,4,c.writeHistory());break;case Q::PublishTick:cr.write=bus(delay-2,2,c.writeHistory());break;default:break;}}else if(auto*t=std::get_if<A>(&j.task)){if(t->stage()==A::Stage::Read)cr.read=bus(0xc3d0+t->offset(),2,last);}else if(auto*t=std::get_if<R>(&j.task)){using Q=R::Stage;switch(t->stage()){case Q::PublishFlags:cr.write=bus(0xcd3d,1,c.writeHistory());break;case Q::PublishNote:cr.write=bus(0xcd34,2,c.writeHistory());break;case Q::PublishPhase:cr.write=bus(0xcd2c,4,c.writeHistory());break;case Q::ReadPeriod:cr.read=bus(0xfffe50,4,last);break;case Q::PublishPeriod:cr.write=bus(0xcd28,4,c.writeHistory());break;default:break;}}return cr;}
 static void project(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<S>(&j.task)){switch(t->stage()){case S::Stage::Clear:c.reg16(0)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case S::Stage::ReadTick:midi_projection::call(c,0x9aa,0x38a8+0x5c*t->slot(),true);break;case S::Stage::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<C>(&j.task)){switch(t->stage()){case C::Stage::Delay:c.reg16(6)=100;val(c,100);break;case C::Stage::Callback:c.reg32(5)=0x43b2;val(c,c.reg32(5));break;case C::Stage::Schedule:midi_projection::call(c,0x394e,0x4452,true);break;case C::Stage::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<A>(&j.task)){using Q=A::Stage;switch(t->stage()){case Q::Retain:push(c,0,false);break;case Q::Clear:c.reg32(0)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::Select:c.reg8(8)=c.reg8(14);val(c,c.reg8(8));break;case Q::Double:{auto old=uint8_t(c.reg8(8));c.ccr=uint8_t((c.ccr&~1)|((old&128)?1:0));c.reg8(8)=int8_t(old<<1);val(c,c.reg8(8));break;}case Q::Bind:c.reg32(0)=int32_t(midi_projection::arithmetic(c,c.reg32(0),0xc3d0,32,false));break;case Q::Subtract:c.reg16(0)=int16_t(midi_projection::arithmetic(c,uint16_t(c.reg16(0)),256,16,true));break;case Q::Clamp:c.reg16(0)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::Publish:c.reg8(14)=c.reg8(0);val(c,c.reg8(14));break;case Q::Restore:pop(c,0,false);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<V>(&j.task)){using Q=V::Stage;switch(t->stage()){case Q::Retain:push(c,6,true);break;case Q::ReadInput:c.reg8(9)=c.reg8(6);val(c,c.reg8(9));break;case Q::Square:c.reg16(1)=int16_t(uint8_t(c.reg8(9))*uint8_t(c.reg8(9)));c.clockI(12);break;case Q::Double:{auto old=uint16_t(c.reg16(1));c.ccr=uint8_t((c.ccr&~1)|((old&0x8000)?1:0));c.reg16(1)=int16_t(old<<1);val(c,c.reg16(1));break;}case Q::RetainGain:c.reg16(9)=c.reg16(1);val(c,c.reg16(9));break;case Q::ClearFraction:c.reg8(1)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::Address:c.reg16(4)=0x13;val(c,0x13);break;case Q::Send:midi_projection::call(c,0x165e,0x4050,true);break;case Q::Restore:pop(c,6,true);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<R>(&j.task)){if(t->stage()==R::Stage::Clear){c.reg32(0)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);}else if(t->stage()==R::Stage::Return)midi_projection::ret(c);}
 }
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;NativeForeground foreground_;NativeDspTransfer dsp_;
};
}
